  const releaseUrl = "https://docs.dynatrace.com/docs/shortlink/release-notes-saas-sprint-320"
  const prompt = `Go to the following release notes page and summarize the main changes.
  Output in Markdown, using clear headings and bullet points for each section. Keep it more then 2000 characters
  URL: ${releaseUrl}`;

  const response = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${openaiApiKey}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      model: "gpt-4.1",
      messages: [
        { "role": "user", "content": prompt }
      ],
      max_tokens: 2048
    })
  });
  const result = await response.json();
  const markdown = result.choices?.[0]?.message?.content || "No summary found";

  return markdown;
}
